<style>
@page{size:A4 portrait;margin:12mm}*{box-sizing:border-box}body{margin:0;background:#eeeae3;color:#30271e;font:11px/1.5 Arial,DejaVu Sans,sans-serif}.document{max-width:186mm;margin:20px auto;padding:12mm;background:#fff}.doc-header{width:100%;border-collapse:collapse;border-bottom:2px solid #b98c45;margin-bottom:16px}.doc-header td{padding:0 0 14px;vertical-align:top}.doc-header .doc-logo-cell{width:112px;text-align:left;vertical-align:middle}.doc-header .doc-company-details{vertical-align:middle}.doc-logo{display:block;width:100px;height:100px;object-fit:contain;margin:0}.doc-company{font-size:18px;font-weight:bold;margin-bottom:5px}.doc-meta{text-align:right;width:30%}.doc-meta strong{font-size:18px;text-transform:uppercase}.doc-info{width:100%;border-spacing:0;margin-bottom:14px;table-layout:fixed}.doc-info td{width:50%;vertical-align:top;padding:12px;background:#f7f0e6;border:4px solid white;border-radius:8px;overflow-wrap:anywhere}.doc-info h2,.doc-box h2{font-size:12px;margin:0 0 5px}.doc-lines{width:100%;border-collapse:collapse;table-layout:fixed}.doc-lines th{background:#f7f0e6;font-size:10px;text-align:left}.doc-lines td,.doc-lines th{padding:8px 5px;border-bottom:1px solid #dfcfb7;vertical-align:top;overflow-wrap:anywhere}.doc-lines thead{display:table-header-group}.doc-lines tr{page-break-inside:avoid}.doc-lines th:nth-child(1){width:10%}.doc-lines th:nth-child(2){width:15%}.doc-lines th:nth-child(3){width:33%}.doc-lines th:nth-child(4){width:8%}.doc-lines th:nth-child(n+5){width:17%}.doc-product-image{display:block;width:44px;height:44px;border:1px solid #dfcfb7;border-radius:4px}.doc-product-no-image{display:block;width:44px;min-height:44px;padding-top:12px;text-align:center;font-size:8px;color:#776b5d;background:#f7f0e6;border:1px solid #dfcfb7;border-radius:4px}.money{text-align:right!important}.doc-totals{width:45%;margin:14px 0 16px auto;border-collapse:collapse;page-break-inside:avoid}.doc-totals td{padding:5px;border-bottom:1px solid #dfcfb7}.doc-totals tr:last-child{font-size:14px;font-weight:bold}.doc-box{background:#f7f0e6;padding:12px;border-radius:8px;margin:12px 0;page-break-inside:avoid}.doc-footer{border-top:1px solid #b98c45;padding-top:10px;margin-top:22px;font-size:10px}.doc-notice{font-size:10px;margin:10px 0}.doc-toolbar{max-width:186mm;margin:15px auto;display:flex;gap:14px;align-items:center}.doc-toolbar button{background:#8e0718;color:white;border:0;border-radius:4px;padding:10px 16px;cursor:pointer}small{font-size:9px}p{margin:4px 0}h1{margin:0;font-size:18px}@media print{body{background:white}.document{margin:0;padding:0;max-width:none}.doc-toolbar{display:none}body{-webkit-print-color-adjust:exact;print-color-adjust:exact}}@media screen and (max-width:600px){.document{margin:0;padding:14px}.doc-company{font-size:15px}.doc-header .doc-logo-cell{width:82px}.doc-logo{width:72px;height:72px}.doc-meta strong{font-size:14px}.doc-totals{width:65%}}
.doc-order-reference{font-size:14px;font-weight:700;text-transform:uppercase}
.doc-info .doc-billing-line{font-size:11px;line-height:1.5}
.doc-info .doc-billing-name{font-size:16px;font-weight:700;line-height:1.3;margin-bottom:5px;word-wrap:break-word}
.doc-info .doc-billing-account{font-size:13px;font-weight:600;margin-bottom:4px}
.doc-financial .doc-lines{font-size:10px;line-height:1.3}
.doc-financial .doc-lines td,.doc-financial .doc-lines th{padding:4px;border-bottom:1px solid #dfcfb7}
.doc-financial .doc-lines th{font-size:9px}
.doc-financial .doc-lines th:first-child{width:7%}
.doc-financial .doc-lines th:nth-child(2){width:12%}
.doc-financial .doc-lines th:nth-child(3){width:31%}
.doc-financial .doc-lines th:nth-child(4),.doc-financial .doc-lines th:nth-child(5){width:16%}
.doc-financial .doc-lines th:nth-child(6){width:6%}
.doc-financial .doc-lines th:nth-child(7){width:12%}
.doc-financial.doc-revised-receipt .doc-info{width:54%}
.doc-financial.doc-revised-receipt .doc-lines th:nth-child(3){width:44%}
.doc-financial.doc-revised-receipt .doc-lines th:nth-child(4){width:16%}
.doc-financial.doc-revised-receipt .doc-lines th:nth-child(5){width:7%}
.doc-financial.doc-revised-receipt .doc-lines th:nth-child(6){width:14%}
.doc-payment-method-amount{width:100%;border-collapse:collapse}
.doc-payment-method-amount th{font-weight:normal;text-align:left}
.doc-payment-method-amount td{font-weight:bold;text-align:right;white-space:nowrap}
.doc-payment-breakdown + .doc-box{margin-top:8px}
.doc-invoice-payment-reference{font-size:11px;margin:8px 0;page-break-after:avoid}
.doc-financial .doc-product-image{width:28px;height:28px;border-radius:3px}
.doc-financial .doc-product-no-image{width:28px;min-height:28px;padding-top:8px;font-size:6px;border-radius:3px}
.doc-financial .doc-lines small{font-size:8px;line-height:1.25}
.doc-financial .doc-footer{margin-top:10px;padding-top:6px}
.doc-revised-receipt .doc-footer{text-align:center}
.doc-financial .doc-delivery{padding:8px 12px}
.doc-payment-summary{width:100%;table-layout:fixed;border-collapse:collapse;margin:14px 0 16px;page-break-inside:avoid;break-inside:avoid}
.doc-payment-summary>tbody>tr>td{vertical-align:top;padding:0;word-wrap:break-word;overflow-wrap:anywhere}
.doc-payment-summary>tbody>tr>.doc-payment-instructions{width:55%;padding-right:18px}
.doc-payment-summary>tbody>tr>.doc-payment-amounts{width:45%}
.doc-payment-summary .doc-box{margin:0}
.doc-payment-summary .doc-delivery{margin-top:8px}
.doc-payment-summary .doc-totals{width:100%;margin:0;table-layout:fixed}
.doc-payment-summary .doc-totals td:first-child{width:65%}
.doc-payment-summary .doc-totals td.money{width:35%;white-space:nowrap}
.doc-delivery-changed .doc-payment-summary{margin:10px 0}
.doc-delivery-changed .doc-payment-summary .doc-box{padding:7px 10px}
.doc-delivery-changed .doc-payment-summary .doc-delivery{margin-top:6px}
.doc-delivery-changed .doc-payment-summary .doc-box p{margin:3px 0}
.doc-delivery-changed .doc-financial-ending{page-break-inside:avoid;break-inside:avoid}
.doc-invoice-aging{width:100%;border-collapse:collapse;font-size:10px}
.doc-invoice-aging th,.doc-info .doc-invoice-aging td{padding:3px 4px;border:0;border-bottom:1px solid #dfcfb7;border-radius:0;background:transparent;vertical-align:middle}
.doc-invoice-aging th{text-align:left;font-weight:400}
.doc-info .doc-invoice-aging td{width:32%;white-space:nowrap;font-weight:700}
.doc-invoice-aging tr:first-child th,.doc-info .doc-invoice-aging tr:first-child td{background:#eadbc3;font-weight:700;font-size:11px}
.doc-invoice-aging tr:last-child th,.doc-info .doc-invoice-aging tr:last-child td{border:0}
.doc-invoice-remittance{background:#f7f0e6;border:1px solid #b98c45;border-radius:8px;margin:9px 0 0;padding:8px;page-break-inside:avoid;break-inside:avoid}
.doc-invoice-remittance table{width:100%;table-layout:fixed;border-collapse:collapse}
.doc-invoice-remittance td{padding:3px 9px;font-size:10px;line-height:1.4;text-align:left;vertical-align:top;word-wrap:break-word}
.doc-invoice-remittance td+td{border-left:1px solid #d8c4a5}
.doc-invoice-remittance .doc-remittance-label{width:17%;padding:0 9px 0 0;vertical-align:middle}
.doc-invoice-remittance .doc-remittance-eft,.doc-invoice-remittance .doc-remittance-cheque{width:29%}
.doc-invoice-remittance .doc-remittance-transfer{width:25%}
.doc-remittance-badge{position:relative;margin:0 12px 0 0;padding:7px 8px;border-radius:4px 0 0 4px;background:#795323;color:#fff;font-size:12px;line-height:12px;text-transform:uppercase}
.doc-remittance-badge span{display:block;width:60px}
.doc-remittance-badge:after{content:"";position:absolute;top:0;left:100%;width:0;height:0;margin-left:-1px;border-top:25px solid transparent;border-bottom:25px solid transparent;border-left:13px solid #795323}
.doc-invoice-remittance h3{font-size:10px;margin:0 0 2px;color:#66471e}
.doc-remittance-icon{width:16px;height:16px;margin-right:5px;vertical-align:middle}
.doc-remittance-email{overflow-wrap:anywhere}
.doc-remittance-routing span{white-space:nowrap}
.doc-remittance-routing span+span{margin-left:6px}
@media screen and (max-width:680px){
    .doc-invoice-remittance table,.doc-invoice-remittance tbody,.doc-invoice-remittance tr,.doc-invoice-remittance td{display:block;width:100%}
    .doc-invoice-remittance td,.doc-invoice-remittance .doc-remittance-eft,.doc-invoice-remittance .doc-remittance-transfer,.doc-invoice-remittance .doc-remittance-cheque{width:100%;padding:6px 4px}
    .doc-invoice-remittance .doc-remittance-label{width:100%;padding:0}
    .doc-invoice-remittance td+td{border-left:0;border-top:1px solid #d8c4a5}
    .doc-invoice-remittance .doc-remittance-label+td{border-top:0}
    .doc-remittance-badge{margin:0;border-radius:4px}
    .doc-remittance-badge span{width:auto}
    .doc-remittance-badge:after{display:none}
}
@media screen and (max-width:600px){
    .doc-financial.doc-revised-receipt .doc-info{width:100%}
    .doc-financial .doc-line-table{overflow-x:auto}
    .doc-financial .doc-line-table .doc-lines{min-width:560px}
    .doc-payment-summary,.doc-payment-summary>tbody,.doc-payment-summary>tbody>tr{display:block}
    .doc-payment-summary>tbody>tr>.doc-payment-instructions,.doc-payment-summary>tbody>tr>.doc-payment-amounts{display:block;width:100%;padding:0}
    .doc-payment-summary>tbody>tr>.doc-payment-amounts{padding-top:12px}
}
</style>
@include('documents.header-style')
